INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c3ee-7ff7-bd8f-d698d5146359'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Express 60 as the product of its prime factors.', '2^2 x 3 x 5', '60 = 2 x 30 = 2 x 2 x 15 = 2^2 x 3 x 5.', 'Easy', '{"tags":"sass-2022-p1,q11a","subtopic":"Prime factorisation","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.326Z'::timestamptz, '2026-09-03T15:48:09.326Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c3f5-736f-8fa9-fa75061a06d5'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'A school buys packs of pens and packs of rulers. There are 60 pens in each pack of pens and 42 rulers in each pack of rulers. The school wants to buy exactly the same number of pens and rulers.

Work out the smallest number of each pack the school should buy.', '7 packs of pens, 10 packs of rulers', 'Need LCM of 60 and 42.
60 = 2^2 x 3 x 5, 42 = 2 x 3 x 7.
LCM = 2^2 x 3 x 5 x 7 = 420.
Packs of pens = 420 / 60 = 7.
Packs of rulers = 420 / 42 = 10.', 'Medium', '{"tags":"sass-2022-p1,q11b","subtopic":"LCM word problems","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.333Z'::timestamptz, '2026-09-03T15:48:09.333Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c405-7b88-a3f5-34cd8f9924ee'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Factorise completely:

3ab - 6ac + 4cd - 2bd.', '(b - 2c)(3a - 2d)', '3ab - 6ac + 4cd - 2bd
= 3a(b - 2c) + 2d(2c - b)
= 3a(b - 2c) - 2d(b - 2c)
= (b - 2c)(3a - 2d).', 'Medium', '{"tags":"sass-2022-p1,q13a","subtopic":"Factorisation by grouping","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.349Z'::timestamptz, '2026-09-03T15:48:09.349Z'::timestamptz) ON CONFLICT (id) DO NOTHING;